### OPTION /screenshot/option/animations-default-disabled

Source: https://github.com/microsoft/playwright/blob/v1.58.2/docs/src/api/params.md

Controls how CSS animations, CSS transitions, and Web Animations are handled during a screenshot, with a default of 'disabled'.

```APIDOC
## OPTION /screenshot/option/animations-default-disabled

### Description
When set to `"disabled"`, stops CSS animations, CSS transitions and Web Animations. Animations get different treatment depending on their duration: finite animations are fast-forwarded to completion, so
```

--------------------------------

### Capture an element screenshot with options like animations and path in Playwright

Source: https://github.com/microsoft/playwright/blob/v1.58.2/docs/src/api/class-locator.md

Demonstrates how to use `Locator.screenshot` with additional options, such as disabling animations and specifying a file path to save the screenshot. This allows for more controlled and customized screenshot captures, ensuring consistent results.

```javascript
await page.getByRole('link').screenshot({ animations: 'disabled', path: 'link.png' });
```

```java
page.getByRole(AriaRole.LINK).screenshot(new Locator.ScreenshotOptions()
    .setAnimations(ScreenshotAnimations.DISABLED)
    .setPath(Paths.get("example.png")));
```

```python async
await page.get_by_role("link").screenshot(animations="disabled", path="link.png")
```

```python sync
page.get_by_role("link").screenshot(animations="disabled", path="link.png")
```

```csharp
await page.GetByRole(AriaRole.Link).ScreenshotAsync(new() {
  Animations = ScreenshotAnimations.Disabled,
  Path = "link.png"
});
```

--------------------------------

### Configure Playwright Viewport and Device Scale Factor (Multi-language)

Source: https://github.com/microsoft/playwright/blob/v1.58.2/docs/src/emulation.md

This snippet provides examples across multiple programming languages (JavaScript, Java, Python, C#) for setting the viewport size and device scale factor. It demonstrates how to configure these properties when creating a new browser context, and how to dynamically resize the viewport for an individual page.

```js
// Create context with given viewport
const context = await browser.newContext({
  viewport: { width: 1280, height: 1024 }
});

// Resize viewport for individual page
await page.setViewportSize({ width: 1600, height: 1200 });

// Emulate high-DPI
const highDPIContext = await browser.newContext({
  viewport: { width: 2560, height: 1440 },
  deviceScaleFactor: 2,
});
```

```java
// Create context with given viewport
BrowserContext context = browser.newContext(new Browser.NewContextOptions()
  .setViewportSize(1280, 1024));

// Resize viewport for individual page
page.setViewportSize(1600, 1200);

// Emulate high-DPI
BrowserContext highDPIContext = browser.newContext(new Browser.NewContextOptions()
  .setViewportSize(2560, 1440)
  .setDeviceScaleFactor(2));
```

```python
# Create context with given viewport
context = await browser.new_context(
  viewport={ 'width': 1280, 'height': 1024 }
)

# Resize viewport for individual page
await page.set_viewport_size({"width": 1600, "height": 1200})

# Emulate high-DPI
high_dpi_context = await browser.new_context(
  viewport={ 'width': 2560, 'height': 1440 },
  device_scale_factor=2,
)
```

```python
# Create context with given viewport
context = browser.new_context(
  viewport={ 'width': 1280, 'height': 1024 }
)

# Resize viewport for individual page
page.set_viewport_size({"width": 1600, "height": 1200})

# Emulate high-DPI
high_dpi_context = browser.new_context(
  viewport={ 'width': 2560, 'height': 1440 },
  device_scale_factor=2,
)
```

```csharp
// Create context with given viewport
await using var context = await browser.NewContextAsync(new()
{
    ViewportSize = new ViewportSize() { Width = 1280, Height = 1024 }
});

// Resize viewport for individual page
await page.SetViewportSizeAsync(1600, 1200);

// Emulate high-DPI
await using var highDPIContext = await browser.NewContextAsync(new()
{
    ViewportSize = new ViewportSize() { Width = 2560, Height = 1440 },
    DeviceScaleFactor = 2
});
```

--------------------------------

### Page.emulateMedia() with reducedMotion option

Source: https://github.com/microsoft/playwright/blob/main/packages/playwright-core/src/client/page.ts

Client-side implementation of page.emulateMedia() showing the exact TypeScript signature including the reducedMotion parameter. Also the BrowserContextOptions type definition showing reducedMotion at the context level.

```typescript
// packages/playwright-core/src/client/page.ts:512-519
async emulateMedia(options: { media?: 'screen' | 'print' | null, colorScheme?: 'dark' | 'light' | 'no-preference' | null, reducedMotion?: 'reduce' | 'no-preference' | null, forcedColors?: 'active' | 'none' | null, contrast?: 'no-preference' | 'more' | null } = {}) {
  await this._channel.emulateMedia({
    media: options.media === null ? 'no-override' : options.media,
    colorScheme: options.colorScheme === null ? 'no-override' : options.colorScheme,
    reducedMotion: options.reducedMotion === null ? 'no-override' : options.reducedMotion,
    forcedColors: options.forcedColors === null ? 'no-override' : options.forcedColors,
    contrast: options.contrast === null ? 'no-override' : options.contrast,
  }, undefined);
}
```

--------------------------------

### Page class: navigation, waiting, screenshot, accessibility locators, and console/error collection

Source: https://github.com/microsoft/playwright/blob/main/packages/playwright-core/src/client/page.ts

The Page class exposes navigation methods (goto, reload, waitForLoadState, waitForURL, waitForNavigation, waitForRequest, waitForResponse), screenshot capture, accessibility-oriented locator creation (getByRole, getByLabel, getByText, getByTestId, getByAltText, getByPlaceholder, getByTitle), and console/error collection APIs (consoleMessages, pageErrors, clearConsoleMessages, clearPageErrors, requests). All navigation and wait methods delegate to the main Frame.

```typescript
async goto(url: string, options?: channels.FrameGotoOptions & TimeoutOptions): Promise<Response | null> {
  return await this._mainFrame.goto(url, options);
}

async waitForLoadState(state?: LifecycleEvent, options?: TimeoutOptions): Promise<void> {
  return await this._mainFrame.waitForLoadState(state, options);
}

async waitForNavigation(options?: WaitForNavigationOptions): Promise<Response | null> {
  return await this._mainFrame.waitForNavigation(options);
}

async waitForURL(url: URLMatch, options?: TimeoutOptions & { waitUntil?: LifecycleEvent }): Promise<void> {
  return await this._mainFrame.waitForURL(url, options);
}

async waitForRequest(urlOrPredicate: string | RegExp | ((r: Request) => boolean | Promise<boolean>), options: TimeoutOptions = {}): Promise<Request> {
  const predicate = async (request: Request) => {
    if (isString(urlOrPredicate) || isRegExp(urlOrPredicate))
      return urlMatches(this._browserContext._options.baseURL, request.url(), urlOrPredicate);
    return await urlOrPredicate(request);
  };
  const trimmedUrl = trimUrl(urlOrPredicate);
  const logLine = trimmedUrl ? `waiting for request ${trimmedUrl}` : undefined;
  return await this._waitForEvent(Events.Page.Request, { predicate, timeout: options.timeout, signal: options.signal }, logLine);
}

async waitForResponse(urlOrPredicate: string | RegExp | ((r: Response) => boolean | Promise<boolean>), options: TimeoutOptions = {}): Promise<Response> {
  const predicate = async (response: Response) => {
    if (isString(urlOrPredicate) || isRegExp(urlOrPredicate))
      return urlMatches(this._browserContext._options.baseURL, response.url(), urlOrPredicate);
    return await urlOrPredicate(response);
  };
  const trimmedUrl = trimUrl(urlOrPredicate);
  const logLine = trimmedUrl ? `waiting for response ${trimmedUrl}` : undefined;
  return await this._waitForEvent(Events.Page.Response, { predicate, timeout: options.timeout, signal: options.signal }, logLine);
}

async screenshot(options: Omit<channels.PageScreenshotOptions, 'mask'> & TimeoutOptions & { path?: string, mask?: api.Locator[] } = {}): Promise<Buffer> {
  const mask = options.mask as Locator[] | undefined;
  const copy: channels.PageScreenshotParams = { ...options, mask: undefined };
  if (!copy.type)
    copy.type = determineScreenshotType(options);
  if (mask) {
    copy.mask = mask.map(locator => ({
      frame: locator._frame._channel,
      selector: locator._selector,
    }));
  }
  const result = await this._channel.screenshot(copy, this._timeoutSettings.timeout(options));
  if (options.path) {
    await mkdirIfNeeded(options.path);
    await fs.promises.writeFile(options.path, result.binary);
  }
  return result.binary;
}

async clearConsoleMessages(): Promise<void> {
  await this._channel.clearConsoleMessages({}, kNoTimeout);
}

async consoleMessages(options?: { filter?: 'all' | 'since-navigation' }): Promise<ConsoleMessage[]> {
  const { messages } = await this._channel.consoleMessages({ filter: options?.filter }, kNoTimeout);
  return messages.map(message => new ConsoleMessage(message, this, null));
}

async clearPageErrors(): Promise<void> {
  await this._channel.clearPageErrors({}, kNoTimeout);
}

async pageErrors(options?: { filter?: 'all' | 'since-navigation' }): Promise<Error[]> {
  const { errors } = await this._channel.pageErrors({ filter: options?.filter }, kNoTimeout);
  return errors.map(error => parseError(error));
}

async requests() {
  const { requests } = await this._channel.requests({}, kNoTimeout);
  return requests.map(request => Request.from(request));
}

getByTestId(testId: string | RegExp): Locator {
  return this.mainFrame().getByTestId(testId);
}

getByAltText(text: string | RegExp, options?: { exact?: boolean }): Locator {
  return this.mainFrame().getByAltText(text, options);
}

getByLabel(text: string | RegExp, options?: { exact?: boolean }): Locator {
  return this.mainFrame().getByLabel(text, options);
}

getByPlaceholder(text: string | RegExp, options?: { exact?: boolean }): Locator {
  return this.mainFrame().getByPlaceholder(text, options);
}

getByText(text: string | RegExp, options?: { exact?: boolean }): Locator {
  return this.mainFrame().getByText(text, options);
}

getByTitle(text: string | RegExp, options?: { exact?: boolean }): Locator {
  return this.mainFrame().getByTitle(text, options);
}

getByRole(role: string, options: ByRoleOptions = {}): Locator {
  return this.mainFrame().getByRole(role, options);
}
```

