import JSZip from 'jszip'

type Scene = {
  id: string
  module: string
  flow: string
  role: string
  screenName: string
  stateName: string
  route: string
  screenshotName: string
  status?: 'success' | 'failed'
  issues?: string[]
}

const input = document.querySelector<HTMLInputElement>('#zipFile')!
const startButton = document.querySelector<HTMLButtonElement>('#start')!
const status = document.querySelector<HTMLElement>('#status')!
const progress = document.querySelector<HTMLProgressElement>('#progress')!
const summary = document.querySelector<HTMLElement>('#summary')!
const errors = document.querySelector<HTMLElement>('#errors')!
let selectedFile: File | null = null
let batchResolver: (() => void) | null = null
let readyResolver: (() => void) | null = null
let completeResolver: (() => void) | null = null

function setStatus(text: string) {
  status.textContent = text
}

function addError(text: string) {
  const item = document.createElement('li')
  item.textContent = text
  errors.appendChild(item)
}

function waitForReady() {
  return new Promise<void>((resolve) => {
    readyResolver = resolve
  })
}

function waitForBatch() {
  return new Promise<void>((resolve) => {
    batchResolver = resolve
  })
}

function waitForComplete() {
  return new Promise<void>((resolve) => {
    completeResolver = resolve
  })
}

window.onmessage = (event) => {
  const message = event.data.pluginMessage
  if (!message) return
  if (message.type === 'ready') {
    summary.textContent = `已创建/复用页面，生成 ${message.createdSections} 个 Section、${message.createdFrames} 个 Frame。`
    readyResolver?.()
    readyResolver = null
  } else if (message.type === 'batch-done') {
    batchResolver?.()
    batchResolver = null
  } else if (message.type === 'progress') {
    progress.max = Math.max(message.total, 1)
    progress.value = message.completed
    setStatus(`导入 ${message.completed}/${message.total}；成功 ${message.success}，失败 ${message.failed}，跳过 ${message.skipped}`)
  } else if (message.type === 'item-error') {
    addError(`${message.id} ${message.screenshotName}：${message.message}`)
  } else if (message.type === 'complete') {
    setStatus(`完成：成功 ${message.success}，失败 ${message.failed}，跳过 ${message.skipped}`)
    summary.textContent = `共处理 ${message.total} 个场景。可关闭插件并在 Atlas｜模块 页面查看。`
    startButton.disabled = false
    completeResolver?.()
    completeResolver = null
  } else if (message.type === 'fatal-error') {
    addError(`插件主线程错误：${message.message}`)
    setStatus('导入中断，请查看错误')
    startButton.disabled = false
  }
}

input.addEventListener('change', () => {
  selectedFile = input.files?.[0] || null
  startButton.disabled = !selectedFile
  setStatus(selectedFile ? `已选择：${selectedFile.name}` : '请选择 figma-import.zip')
})

startButton.addEventListener('click', async () => {
  if (!selectedFile) return
  startButton.disabled = true
  errors.innerHTML = ''
  progress.value = 0

  try {
    setStatus('读取 ZIP 与 Manifest…')
    const zip = await JSZip.loadAsync(await selectedFile.arrayBuffer())
    const manifestEntry = zip.file('capture-manifest.json')
    if (!manifestEntry) throw new Error('ZIP 缺少 capture-manifest.json')
    const manifest = JSON.parse(await manifestEntry.async('string')) as Scene[]
    if (!Array.isArray(manifest) || !manifest.length) throw new Error('capture-manifest.json 不是非空数组')

    const ids = new Set<string>()
    for (const scene of manifest) {
      if (!scene.id || !scene.module || !scene.flow || !scene.screenName || !scene.screenshotName) {
        throw new Error(`Manifest 场景字段不完整：${JSON.stringify(scene)}`)
      }
      if (ids.has(scene.id)) throw new Error(`Manifest 场景 ID 重复：${scene.id}`)
      ids.add(scene.id)
    }

    const missing = manifest.filter((scene) => scene.status !== 'failed' && !zip.file(`images/${scene.screenshotName}`))
    for (const scene of missing) addError(`缺少图片：${scene.id} images/${scene.screenshotName}`)

    parent.postMessage({ pluginMessage: { type: 'initialize', manifest } }, '*')
    await waitForReady()

    const importable = manifest.filter((scene) => scene.status !== 'failed' && zip.file(`images/${scene.screenshotName}`))
    const batchSize = 6
    for (let offset = 0; offset < importable.length; offset += batchSize) {
      const scenes = importable.slice(offset, offset + batchSize)
      const items = await Promise.all(scenes.map(async (scene) => ({
        id: scene.id,
        screenshotName: scene.screenshotName,
        bytes: await zip.file(`images/${scene.screenshotName}`)!.async('uint8array'),
      })))
      parent.postMessage({ pluginMessage: { type: 'image-batch', items } }, '*')
      await waitForBatch()
    }

    parent.postMessage({ pluginMessage: { type: 'finish' } }, '*')
    await waitForComplete()
  } catch (error) {
    addError(error instanceof Error ? error.message : String(error))
    setStatus('读取或导入失败')
    startButton.disabled = false
  }
})

import fs from 'node:fs/promises'
import path from 'node:path'
import process from 'node:process'
import JSZip from 'jszip'
import { PNG } from 'pngjs'

const zipPath = path.resolve(process.argv[2] || '')
const buffer = await fs.readFile(zipPath)
const zip = await JSZip.loadAsync(buffer)
const manifestEntry = zip.file('capture-manifest.json')
if (!manifestEntry) throw new Error('ZIP 缺少 capture-manifest.json')
const manifest = JSON.parse(await manifestEntry.async('string'))
if (!Array.isArray(manifest) || !manifest.length) throw new Error('Manifest 为空或格式错误')

let checked = 0
for (const scene of manifest) {
  if (scene.status === 'failed') continue
  const entry = zip.file(`images/${scene.screenshotName}`)
  if (!entry) throw new Error(`ZIP 缺少图片：${scene.screenshotName}`)
  const image = PNG.sync.read(await entry.async('nodebuffer'))
  if (image.width > 4096 || image.height > 4096) throw new Error(`图片超过 4096：${scene.screenshotName}`)
  if (image.width !== scene.imageWidth || image.height !== scene.imageHeight) {
    throw new Error(`Manifest 尺寸不一致：${scene.screenshotName}`)
  }
  checked += 1
}

process.stdout.write(`ZIP_SMOKE_PASS scenes=${manifest.length} images=${checked} path=${zipPath}\n`)

{
  "name": "prototype-screenshot-atlas-importer",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "build": "node ./scripts/build.mjs",
    "test:zip": "node ./tests/zip-smoke.mjs ../../artifacts/prototype-snapshots/figma-import.zip",
    "verify": "npm run build && npm run test:zip"
  },
  "dependencies": {
    "jszip": "3.10.1"
  },
  "devDependencies": {
    "esbuild": "0.27.2",
    "typescript": "6.0.2"
  }
}

type CaptureAction = {
  type: string
  target: string
  value?: string
}

type CaptureScene = {
  id: string
  module: string
  flow: string
  role: string
  screenName: string
  stateName: string
  route: string
  viewport?: { width: number; height: number }
  screenshotName: string
  notes?: string
  actions?: CaptureAction[]
  status?: 'success' | 'failed'
  issues?: string[]
  needsManualReview?: boolean
  imageWidth?: number
  imageHeight?: number
}

type ImageBatchItem = {
  id: string
  screenshotName: string
  bytes: Uint8Array
}

type SceneNodes = {
  frameId: string
  imageNodeId?: string
  scene: CaptureScene
}

const FRAME_GAP_X = 160
const FRAME_GAP_Y = 200
const SECTION_PADDING = 120
const META_HEIGHT = 156
const SECTION_GAP_Y = 360
const MAX_IMAGE_EDGE = 4096
const DEFAULT_IMAGE_WIDTH = 1440
const DEFAULT_IMAGE_HEIGHT = 900
const pagePrefix = 'Atlas｜'
const sceneNodes = new Map<string, SceneNodes>()
let totalScenes = 0
let completedImages = 0
let successImages = 0
let failedImages = 0
let skippedImages = 0

figma.showUI(__html__, { width: 560, height: 720, themeColors: true })

function rgb(hex: string): RGB {
  const value = hex.replace('#', '')
  return {
    r: Number.parseInt(value.slice(0, 2), 16) / 255,
    g: Number.parseInt(value.slice(2, 4), 16) / 255,
    b: Number.parseInt(value.slice(4, 6), 16) / 255,
  }
}

function solid(hex: string): SolidPaint {
  return { type: 'SOLID', color: rgb(hex) }
}

async function loadFonts() {
  await figma.loadFontAsync({ family: 'Inter', style: 'Regular' })
  await figma.loadFontAsync({ family: 'Inter', style: 'Semi Bold' })
}

function createText(
  text: string,
  size: number,
  color: string,
  width: number,
  style: 'Regular' | 'Semi Bold' = 'Regular',
) {
  const node = figma.createText()
  node.fontName = { family: 'Inter', style }
  node.fontSize = size
  node.characters = text
  node.fills = [solid(color)]
  node.textAutoResize = 'HEIGHT'
  node.resize(width, Math.max(size * 1.4, 20))
  return node
}

function actionSummary(scene: CaptureScene) {
  if (!scene.actions?.length) return '触发方式：直接进入页面'
  return `触发方式：${scene.actions.map((action) => `${action.type}「${action.target}」${action.value ? ` = ${action.value}` : ''}`).join(' → ')}`
}

function isSupplementary(scene: CaptureScene) {
  const text = `${scene.stateName} ${scene.screenName} ${(scene.issues || []).join(' ')}`
  return /(空|错误|异常|失败|权限|校验|弹窗|抽屉|维护|导入|创建|新增|表单|待执行)/.test(text)
}

function uniqueSectionName(page: PageNode, flow: string) {
  const base = `流程｜${flow}`
  const existing = page.children.filter((node) => node.type === 'SECTION' && node.name.startsWith(base))
  return existing.length ? `${base}｜导入 ${existing.length + 1}` : base
}

function pageForModule(moduleName: string) {
  const name = `${pagePrefix}${moduleName}`
  const existing = figma.root.children.find((page) => page.name === name)
  if (existing) return existing
  const page = figma.createPage()
  page.name = name
  return page
}

function nextSectionY(page: PageNode) {
  const sections = page.children.filter((node) => node.type === 'SECTION')
  return sections.length ? Math.max(...sections.map((node) => node.y + node.height)) + SECTION_GAP_Y : 0
}

function sceneImageSize(scene: CaptureScene) {
  const width = scene.imageWidth || scene.viewport?.width || DEFAULT_IMAGE_WIDTH
  const height = scene.imageHeight || scene.viewport?.height || DEFAULT_IMAGE_HEIGHT
  return {
    width: Math.min(width, MAX_IMAGE_EDGE),
    height: Math.min(height, MAX_IMAGE_EDGE),
  }
}

function createSceneFrame(scene: CaptureScene) {
  const imageSize = sceneImageSize(scene)
  const contentWidth = Math.max(imageSize.width, 720)
  const frameWidth = contentWidth + 64
  const frame = figma.createFrame()
  frame.name = `${scene.id} ${scene.screenName}｜${scene.stateName}`
  frame.layoutMode = 'VERTICAL'
  frame.primaryAxisSizingMode = 'AUTO'
  frame.counterAxisSizingMode = 'FIXED'
  frame.counterAxisAlignItems = 'MIN'
  frame.itemSpacing = 12
  frame.paddingTop = 28
  frame.paddingRight = 32
  frame.paddingBottom = 28
  frame.paddingLeft = 32
  frame.resize(frameWidth, 100)
  frame.fills = [solid(scene.status === 'failed' ? '#FFF7F0' : '#FFFFFF')]
  frame.strokes = [solid(scene.status === 'failed' ? '#D4380D' : '#D9DEE7')]
  frame.strokeWeight = 1
  frame.cornerRadius = 12
  frame.clipsContent = false

  frame.appendChild(createText(`${scene.id} ${scene.screenName}｜${scene.stateName}`, 24, '#172033', contentWidth, 'Semi Bold'))
  frame.appendChild(createText(`角色：${scene.role}　 路由：${scene.route}　 流程：${scene.flow}`, 14, '#4F5B6E', contentWidth))

  let imageNodeId: string | undefined
  if (scene.status !== 'failed') {
    const imageNode = figma.createRectangle()
    imageNode.name = `截图｜${scene.screenshotName}`
    imageNode.resize(imageSize.width, imageSize.height)
    imageNode.fills = [solid('#EEF1F5')]
    imageNode.cornerRadius = 4
    frame.appendChild(imageNode)
    imageNodeId = imageNode.id
  } else {
    const failure = createText(
      `截图失败占位\n${(scene.issues || ['未提供失败原因']).join('\n')}`,
      18,
      '#B42318',
      contentWidth,
      'Semi Bold',
    )
    frame.appendChild(failure)
  }

  const notes = [
    actionSummary(scene),
    scene.notes ? `备注：${scene.notes}` : '',
    scene.needsManualReview ? '人工检查：需要人工复核' : '',
  ].filter(Boolean).join('\n')
  frame.appendChild(createText(notes || '备注：无', 13, '#667085', contentWidth))

  return { frame, imageNodeId }
}

async function initializeAtlas(manifest: CaptureScene[]) {
  await loadFonts()
  totalScenes = manifest.length
  sceneNodes.clear()
  const modules = new Map<string, CaptureScene[]>()
  for (const scene of manifest) {
    const items = modules.get(scene.module) || []
    items.push(scene)
    modules.set(scene.module, items)
  }

  const createdPages: string[] = []
  const createdSections: string[] = []
  const createdFrames: string[] = []

  for (const [moduleName, moduleScenes] of modules) {
    const page = pageForModule(moduleName)
    await figma.setCurrentPageAsync(page)
    createdPages.push(page.id)
    const flows = new Map<string, CaptureScene[]>()
    for (const scene of moduleScenes.sort((a, b) => a.id.localeCompare(b.id, 'zh-CN', { numeric: true }))) {
      const items = flows.get(scene.flow) || []
      items.push(scene)
      flows.set(scene.flow, items)
    }

    let sectionY = nextSectionY(page)
    for (const [flowName, flowScenes] of flows) {
      const section = figma.createSection()
      section.name = uniqueSectionName(page, flowName)
      section.x = 0
      section.y = sectionY
      section.fills = [solid('#F4F6F9')]
      createdSections.push(section.id)

      const mainScenes = flowScenes.filter((scene) => !isSupplementary(scene))
      const supplementaryScenes = flowScenes.filter(isSupplementary)
      const rows = [mainScenes, supplementaryScenes].filter((row) => row.length)
      let rowY = SECTION_PADDING
      let sectionWidth = 0

      for (const row of rows) {
        let rowX = SECTION_PADDING
        let rowHeight = 0
        for (const scene of row) {
          const { frame, imageNodeId } = createSceneFrame(scene)
          section.appendChild(frame)
          frame.x = rowX
          frame.y = rowY
          rowX += frame.width + FRAME_GAP_X
          rowHeight = Math.max(rowHeight, frame.height)
          sectionWidth = Math.max(sectionWidth, rowX - FRAME_GAP_X + SECTION_PADDING)
          sceneNodes.set(scene.id, { frameId: frame.id, imageNodeId, scene })
          createdFrames.push(frame.id)
        }
        rowY += rowHeight + FRAME_GAP_Y
      }

      const sectionHeight = Math.max(rowY - FRAME_GAP_Y + SECTION_PADDING, 480)
      section.resizeWithoutConstraints(Math.max(sectionWidth, 960), sectionHeight)
      sectionY += section.height + SECTION_GAP_Y
    }
  }

  figma.ui.postMessage({
    type: 'ready',
    total: totalScenes,
    createdPages: createdPages.length,
    createdSections: createdSections.length,
    createdFrames: createdFrames.length,
  })
}

async function importImage(item: ImageBatchItem) {
  const target = sceneNodes.get(item.id)
  if (!target?.imageNodeId) {
    skippedImages += 1
    return
  }
  const imageNode = await figma.getNodeByIdAsync(target.imageNodeId)
  if (!imageNode || imageNode.type !== 'RECTANGLE') {
    throw new Error(`找不到截图占位节点：${item.id}`)
  }
  const bytes = item.bytes instanceof Uint8Array ? item.bytes : new Uint8Array(item.bytes)
  const image = figma.createImage(bytes)
  const size = await image.getSizeAsync()
  if (size.width > MAX_IMAGE_EDGE || size.height > MAX_IMAGE_EDGE) {
    throw new Error(`图片超过 4096×4096：${item.screenshotName} ${size.width}×${size.height}`)
  }
  imageNode.resize(size.width, size.height)
  imageNode.fills = [{ type: 'IMAGE', imageHash: image.hash, scaleMode: 'FIT' }]
  successImages += 1
}

async function importBatch(items: ImageBatchItem[]) {
  for (const item of items) {
    try {
      await importImage(item)
    } catch (error) {
      failedImages += 1
      figma.ui.postMessage({
        type: 'item-error',
        id: item.id,
        screenshotName: item.screenshotName,
        message: error instanceof Error ? error.message : String(error),
      })
    } finally {
      completedImages += 1
      figma.ui.postMessage({
        type: 'progress',
        completed: completedImages,
        total: totalScenes,
        success: successImages,
        failed: failedImages,
        skipped: skippedImages,
      })
    }
  }
  figma.ui.postMessage({ type: 'batch-done' })
}

figma.ui.onmessage = async (message: { type: string; manifest?: CaptureScene[]; items?: ImageBatchItem[] }) => {
  try {
    if (message.type === 'initialize' && message.manifest) {
      await initializeAtlas(message.manifest)
      return
    }
    if (message.type === 'image-batch' && message.items) {
      await importBatch(message.items)
      return
    }
    if (message.type === 'finish') {
      const firstFrame = sceneNodes.values().next().value as SceneNodes | undefined
      if (firstFrame) {
        const node = await figma.getNodeByIdAsync(firstFrame.frameId)
        if (node && 'type' in node && node.type === 'FRAME') figma.viewport.scrollAndZoomIntoView([node])
